class Solution:
    def crossEntropy(self, probs: List[List[float]], labels: List[int]) -> float:
        eps = 1e-12
        total = 0.0
        for row, y in zip(probs, labels):
            p = min(max(row[y], eps), 1.0 - eps)
            total -= math.log(p)
        return total / len(labels)

